289	    /**
290	     * Computes the customer code for an owner about to be created, de-duplicated against the codes
291	     * already assigned to existing owners so that distinct owners always receive distinct codes.
292	     *
293	     * @return the owner's unique customer code
294	     */
295	    private String assignCustomerCode(Owner owner) {
296	        String region = LocalityResolver.localityOf(owner.getPostcode(), owner.getCity());
297	        String baseCode = customerCodeGenerator.generate(
298	            region, owner.getTelephone(), owner.getLastName());
299	        List<String> takenCodes = clinicService.findOwnersByCustomerCodeStartingWith(baseCode)
300	            .stream()
301	            .map(Owner::getCustomerCode)
302	            .toList();
303	        return customerCodeGenerator.deduplicate(baseCode, takenCodes);
304	    }
305	
306	    /**
307	     * Applies the household-membership rule once the owner has cleared hard duplicate detection.
308	     * When the owner joins an existing household (same last name and postcode) its membership level
309	     * is capped to at most one above the highest level among the existing members. A member declared
310	     * with {@code sharesHousehold} is, being knowingly registered, not treated as a suspected
311	     * duplicate; an undeclared one still runs the ordinary possible-duplicate detection. When the
312	     * owner starts a new household no cap applies and possible-duplicate detection runs as usual.
313	     */
314	    private void applyHouseholdRule(Owner owner, OwnerFieldsDto ownerFieldsDto,
315	                                    List<Owner> householdMembers, Collection<Owner> sameLastName) {
316	        if (householdMembers.isEmpty()) {
317	            flagPossibleDuplicate(owner, sameLastName);
318	            return;
319	        }
320	        owner.setMembershipLevelCap(MembershipLevelCalculator.householdLevelCeiling(householdMembers));
321	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
322	            owner.setPossibleDuplicate(false);
323	            owner.setPossibleDuplicateOf(null);
324	        } else {
325	            flagPossibleDuplicate(owner, sameLastName);
326	        }
327	    }
328	
329	    /**
330	     * Rejects the owner when its whole derived {@link IdentityKey} already belongs to another
331	     * owner. A full-key match requires an equal telephone, so only owners with the same
332	     * (already normalized) telephone are compared.
333	     *
334	     * @throws DuplicateIdentityException if an existing owner shares the new owner's identity key
335	     */
336	    private void rejectIfDuplicateIdentity(Owner owner) {
337	        Collection<Owner> sameTelephone =
338	            activeOwners(this.clinicService.findOwnersByTelephone(owner.getTelephone()));
339	        if (identityDuplicateValidator.isDuplicate(owner, sameTelephone)) {
340	            throw new DuplicateIdentityException(IdentityKey.of(owner));
341	        }
342	    }
343	
344	    /**
345	     * Filters out soft-deleted owners, so the create endpoint's duplicate and identity checks
346	     * consider only owners that are still active. A soft-deleted owner keeps its row but is
347	     * treated as absent for the purpose of detecting duplicates of a newly created owner.
348	     */
349	    private List<Owner> activeOwners(Collection<Owner> owners) {
350	        return owners.stream().filter(candidate -> !candidate.isDeleted()).toList();
351	    }
352	
353	    /**
354	     * Flags the owner as a soft (possible) duplicate when it is not a hard duplicate yet shares an
355	     * existing owner's last name and postcode with a different telephone. The matching owner's id
356	     * is recorded in {@code possibleDuplicateOf}; when nothing matches the owner is stamped as not
357	     * a possible duplicate. Called after {@link #rejectIfDuplicateIdentity(Owner)}, so any candidate
358	     * seen here is guaranteed not to be a hard duplicate.
359	     */
360	    private void flagPossibleDuplicate(Owner owner, Collection<Owner> sameLastName) {
361	        Owner match = possibleDuplicateDetector.findPossibleDuplicate(owner, sameLastName).orElse(null);
362	        owner.setPossibleDuplicate(match != null);
363	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
364	    }
