7	/** capacity-warning: 'capacityWarning' is true when the owner's city already holds 40-49
8	 * owners (approaching the 50 hard limit). Fill a fresh city to 40, then the next owner in it warns. */
9	class AcceptanceTest extends AcceptanceBase {
10	
11		@Test
12		void coreWarnsWhenApproachingCapacity() throws Exception {
13			String city = "Warn" + seq();
14			fillCity(city, 40);
15			ObjectNode o = ownerNode();
16			o.put("city", city);
17			int id = createOwnerOk(o);
18			getOwner(id).andExpect(jsonPath("$.capacityWarning").value(true));
19		}
