289	        this.pets = pets;
290	    }
291	
292	    public List<Pet> getPets() {
293	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
294	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
295	        return Collections.unmodifiableList(sortedPets);
296	    }
297	
298	    public void setPets(List<Pet> pets) {
299	        this.pets = new HashSet<>(pets);
300	    }
301	
302	    public void addPet(Pet pet) {
303	        getPetsInternal().add(pet);
304	        pet.setOwner(this);
