306	
307	    /**
308	     * Return the Pet with the given name, or null if none found for this Owner.
309	     *
310	     * @param name to test
311	     * @return true if pet name is already in use
312	     */
313	    public Pet getPet(String name) {
314	        return getPet(name, false);
315	    }
316	
317	    /**
318	     * Return the Pet with the given name, or null if none found for this Owner.
319	     *
320	     * @param name to test
321	     * @return true if pet name is already in use
322	     */
323	    public Pet getPet(String name, boolean ignoreNew) {
324	        name = name.toLowerCase();
325	        for (Pet pet : getPetsInternal()) {
326	            if (!ignoreNew || !pet.isNew()) {
327	                String compName = pet.getName();
328	                compName = compName.toLowerCase();
329	                if (compName.equals(name)) {
330	                    return pet;
331	                }
332	            }
333	        }
334	        return null;
335	    }
336	
337	    public Pet getPet(Integer petId) {
338	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
339	    }
340	
341	    @Override
342	    public String toString() {
343	        return new ToStringCreator(this)
344	
345	            .append("id", this.getId())
346	            .append("new", this.isNew())
347	            .append("lastName", this.getLastName())
348	            .append("firstName", this.getFirstName())
349	            .append("title", this.title)
350	            .append("address", this.address)
351	            .append("addressLine1", this.addressLine1)
352	            .append("addressLine2", this.addressLine2)
353	            .append("city", this.city)
354	            .append("telephone", this.telephone)
355	            .append("email", this.email)
356	            .append("postcode", this.postcode)
357	            .append("registrationDate", this.registrationDate)
358	            .append("birthDate", this.birthDate)
359	            .append("customerCode", this.customerCode)
360	            .append("householdId", this.householdId)
361	            .append("namesakeCount", this.namesakeCount)
362	            .append("householdSize", this.householdSize)
363	            .append("membershipLevelCap", this.membershipLevelCap)
364	            .append("bulkSignupWarning", this.bulkSignupWarning)
365	            .append("possibleDuplicate", this.possibleDuplicate)
366	            .append("possibleDuplicateOf", this.possibleDuplicateOf)
367	            .append("deleted", this.deleted)
368	            .toString();
369	    }
370	}
